// AŞAMA: Dinamik Özellik Motoru (Attribute Engine)
function generateAdvancedStats() {
    leagueData.players.forEach(p => {
        // YENİ: Gizli Potansiyel (Hidden Potential) Sistemi
        if (!p.hiddenPotential) {
            if (p.age <= 24) {
                // %10 ihtimalle Wonderkid (85-99 arası)
                if (Math.random() < 0.10) {
                    p.hiddenPotential = Math.max(p.power, Math.floor(Math.random() * 15) + 85);
                } else {
                    p.hiddenPotential = Math.min(99, p.power + Math.floor(Math.random() * 15));
                }
            } else {
                // Yaşlı oyuncuların potansiyeli mevcut güçlerine yakındır
                p.hiddenPotential = Math.min(99, p.power + Math.floor(Math.random() * 3));
            }
        }

        let pFactor = p.power / 100;
        let sFactor = p.speed / 5.5;
        
        // 1. Teknik (Technical)
        p.finishing = p.power; 
        if (p.tacticalRole === 'poacher' || p.tacticalRole === 'target_man' || p.position === 'Forvet') {
            p.finishing = Math.min(99, p.power + 5); 
        }
        p.firstTouch = Math.min(99, Math.floor(p.power * 0.9 + (p.tacticalRole === 'playmaker' ? 10 : 0)));
        p.dribbling = Math.min(99, Math.floor(p.speed * 15 + p.power * 0.4));
        
        // 2. Zihinsel (Mental)
        p.positioning = Math.min(99, Math.floor(p.power * 0.85 + (p.age > 30 ? 10 : 0)));
        if (p.tacticalRole === 'poacher' || p.tacticalRole === 'inside_forward') p.positioning = Math.min(99, p.positioning + 8);
        
        p.composure = Math.min(99, Math.floor(p.power * 0.8));
        if (p.mentalTrait === 'elite') p.composure = Math.min(99, p.composure + 15);
        if (p.mentalTrait === 'fragile') p.composure = Math.max(10, p.composure - 20);
        
        p.anticipation = Math.min(99, Math.floor((p.power + (p.age > 30 ? 15 : 0)) * 0.9));
        
        // 3. Fiziksel (Physical)
        p.acceleration = Math.min(99, Math.floor(p.speed * 18));
        p.balance = Math.min(99, Math.floor(p.power * 0.9 + (p.tacticalRole === 'target_man' || p.tacticalRole === 'stopper' ? 10 : 0)));
        p.agility = Math.min(99, Math.floor(p.speed * 16));
        
        p.traits = [];

        // === ALT KLASMAN (Tier 3 / Tier 4) CEZALARI (Power 50-70) ===
        if (p.power >= 50 && p.power <= 70) {
            p.firstTouch = Math.floor(Math.random() * 25) + 40; // 40-65 arası
            p.finishing = Math.floor(Math.random() * 20) + 50;  // 50-70 arası
            p.composure = Math.floor(Math.random() * 25) + 30;  // 30-55 arası (Panik)
            p.positioning = Math.floor(Math.random() * 20) + 40; // 40-60 arası (Ofsayt makinesi)
            
            // Başsız Tavuk (Sadece Hız)
            if (p.speed > 4.5 && p.power < 65) {
                p.dribbling = 35; 
            }
            // Hantal Oduncu (Sadece Güç)
            if (p.power > 75 && p.speed < 3.0) { // Though power is 50-70 above, let's keep logic intact
                p.agility = 30;
            }
            if (p.power > 65 && p.speed < 3.2 && p.power <= 75) {
                p.agility = 30; // Hantal ceza
            }

            // Kötü Rozetler
            if (Math.random() < 0.6) p.traits.push('always_offside');
            if (Math.random() < 0.5) p.traits.push('dwells_on_ball');
            if (Math.random() < 0.3) p.traits.push('shoots_from_distance');
            if (Math.random() < 0.5) p.traits.push('weak_foot_problem');
        }

        // === DÜNYA YILDIZI ROZETLERİ (Power >= 90) ===
        if (p.power >= 90) {
            if (p.positioning > 93 && Math.random() < 0.7) p.traits.push('beats_offside_trap');
            if (p.finishing > 94 && Math.random() < 0.6) p.traits.push('places_shots');
            if (p.firstTouch > 92 && Math.random() < 0.5) p.traits.push('first_time_shots');
        }

        // 80-90 Arası (Tier 2): Sağlam oyuncular, ufak bonuslar
        if (p.power >= 80 && p.power < 90) {
            p.finishing += 5;
            p.firstTouch += 5;
            p.composure += 5;
        }
        
        // Ekstra Manuel Ayar
        if (p.name.includes("Icardi") || p.name.includes("Haaland") || p.name.includes("Mbappé") || p.name.includes("Osimhen")) {
            p.finishing = Math.max(96, p.finishing);
            p.firstTouch = Math.max(92, p.firstTouch);
            p.positioning = Math.max(97, p.positioning);
            p.composure = Math.max(95, p.composure);
            p.anticipation = Math.max(94, p.anticipation);
            p.acceleration = Math.max(90, p.acceleration);
            if (!p.traits.includes('places_shots')) p.traits.push('places_shots');
            if (!p.traits.includes('first_time_shots')) p.traits.push('first_time_shots');
            if (p.tacticalRole === 'poacher' && !p.traits.includes('beats_offside_trap')) p.traits.push('beats_offside_trap');
        }
    });
}

