// --- 7 FUTBOLCU PROFİLİ OTOMATİK ATAMA SİSTEMİ ---
if (leagueData && leagueData.players) {
    leagueData.players.forEach(p => {
        if (!p.tacticalRole || p.tacticalRole === 'classic') {
            let pos = p.position || "";
            let mental = p.mentalTrait || "consistent"; // elite, aggressive, creative, consistent, fragile
            
            // KARAKTERE (MENTAL TRAIT) GÖRE GİZLİ PROFİL ATAMASI
            if (pos.includes('Bek')) {
                // Agresif bekler çizgi otobanı olur, diğerleri joker
                p.tacticalRole = (mental === 'aggressive' || mental === 'elite') ? 'attacking_fullback' : 'utility';
            } else if (pos.includes('Stoper')) {
                // Lider veya agresif stoperler Patron Stoper olur
                p.tacticalRole = (mental === 'elite' || mental === 'aggressive') ? 'stopper' : 'utility';
            } else if (pos === 'On Numara') {
                p.tacticalRole = 'playmaker'; // On numara her zaman maestro'dur
            } else if (pos.includes('Ortasaha') || pos === 'Ön Libero') {
                if (mental === 'aggressive') p.tacticalRole = 'box_to_box';
                else if (mental === 'elite' || mental === 'creative') p.tacticalRole = 'playmaker';
                else p.tacticalRole = 'utility';
            } else if (pos.includes('Kanat')) {
                // Yaratıcı kanatlar sihirbaz olur
                p.tacticalRole = (mental === 'creative' || mental === 'elite') ? 'winger' : 'utility';
            } else if (pos === 'Forvet') {
                // Fırsatçı (Poacher) genelde kırılgan (sadece gol atar) veya elit karakterlidir
                p.tacticalRole = (mental === 'fragile' || mental === 'elite') ? 'poacher' : 'utility';
            } else if (pos === 'Kaleci') {
                p.tacticalRole = 'sweeper_keeper';
            } else {
                p.tacticalRole = 'utility'; 
            }
        }
        
        // Bazı bilindik isimlere özel atamalar (Örnek)
        if (p.name.includes("Torreira") || p.name.includes("Kanté") || p.name.includes("Gattuso")) p.tacticalRole = 'box_to_box';
        if (p.name.includes("Icardi") || p.name.includes("Dzeko") || p.name.includes("Haaland")) p.tacticalRole = 'poacher';
        if (p.name.includes("Ferdi") || p.name.includes("Alexander-Arnold")) p.tacticalRole = 'attacking_fullback';
        if (p.name.includes("De Bruyne") || p.name.includes("Ødegaard")) p.tacticalRole = 'playmaker';
        if (p.name.includes("Vinícius") || p.name.includes("Quaresma")) p.tacticalRole = 'winger';
        if (p.name.includes("Ramos") || p.name.includes("van Dijk")) p.tacticalRole = 'stopper';
        if (p.name.includes("Barış Alper") || p.name.includes("Nacho")) p.tacticalRole = 'utility';
    });
}

// --- TARAFTAR PROFİLLERİ (FAN PROFILES) ATAMASI ---
if (leagueData && leagueData.teams) {
    leagueData.teams.forEach(t => {
        if (!t.fanProfile) {
            let name = t.name.toLowerCase();
            if (name.includes('göztepe') || name.includes('kocaelispor') || name.includes('dortmund') || name.includes('amed') || name.includes('trabzonspor')) {
                t.fanProfile = 'ultras';
            } else if (name.includes('galatasaray') || name.includes('fenerbahçe') || name.includes('beşiktaş') || name.includes('roma') || name.includes('bologna')) {
                t.fanProfile = Math.random() < 0.5 ? 'cekirdekci' : 'ultras'; // Büyük ama sabırsız kitle
            } else if (name.includes('real madrid') || name.includes('manchester city') || name.includes('psg') || name.includes('bayern')) {
                t.fanProfile = 'glory_hunters'; // İyi gün taraftarı
            } else if (name.includes('arsenal') || name.includes('brighton') || name.includes('bayer leverkusen') || name.includes('basaksehir')) {
                t.fanProfile = 'analist'; // Taktik sevdalıları
            } else if (name.includes('al-nassr') || name.includes('inter') || name.includes('manchester utd')) {
                t.fanProfile = 'oyuncu_fanatigi'; // Bireysel hayranlar
            } else if (name.includes('genclerbirligi') || name.includes('konyaspor') || name.includes('como') || name.includes('bodo')) {
                t.fanProfile = 'nostaljik'; // Eski kafalılar
            } else {
                let profiles = ['ultras', 'cekirdekci', 'analist', 'glory_hunters', 'oyuncu_fanatigi', 'nostaljik'];
                t.fanProfile = profiles[Math.floor(Math.random() * profiles.length)];
            }
        }
    });
}
